# flake8: noqa

import collections
import copy
import pickle
import multiprocessing
import random
import select
import socket
import threading
import time
import traceback

import ta_emss.utilities.xterm_lib.asncoder as asncoder
import ta_emss.utilities.xterm_lib.message_def as message_def
import ta_emss.utilities.xterm_lib.xsocket as xsocket
from ta_emss.utilities.xterm_lib.timer import Timer
from ta_emss.utilities.xterm_lib.flogger import Flogger
from ta_emss.utilities.xterm_lib.defs import *

g_debug = False
g_enable_prints = True

MAX_PENDING_TASKS = 20


class ENBConn(threading.Thread):
    def __init__(
        self,
        enb_config,
        local_ip,
        farend_ip=None,
        client=None,
        x2ap_config=None,
        logger=None,
        parent_sch=None,
        log_screen=True,
        log_file=True,
        asn_coder=None,
        endc=False,
    ):
        super(ENBConn, self).__init__()
        self.local_ip = local_ip

        self.farend_ip = farend_ip
        self.client = client
        self.socket = None
        self.asn_coder = asn_coder
        self.endc = endc

        self.x2ap_config = x2ap_config if x2ap_config is not None else {}

        self.port = 36422
        self.new_enb_config = copy.deepcopy(enb_config)
        self.enb_config = copy.deepcopy(enb_config)
        self.running = False
        self.logger = logger
        self.log_screen = log_screen
        self.log_file = log_file
        self.parent_sch = parent_sch
        self.num_msg_rx = 0
        self.num_msg_tx = 0
        self.errors = 0
        self.hb = 0
        self.enb_id = self.enb_config["ENB_ID"]
        self.mcc = self.enb_config["MCC"]
        self.mnc = self.enb_config["MNC"]
        self.dl_earfcn = self.enb_config["DL_EARFCN"]
        self.link_state = None  # "INIT", "CONNECTED", "CLOSED"
        self.link_substate = (
            None  # "NONE", "SETUP_REQUEST", "CONFIG_UPDATE", "CONFIG_UPDATE_FAILURE"
        )
        self.tasks = collections.deque()
        self.task_map = {
            TSK_X2_SETUP: self.setup_link,
            TSK_X2_RESET: self.disconnect,
            TSK_ENB_CONFIGURATION_UPDATE: self.send_update,
            TSK_CFG_INC_PCI: self.cfg_inc_pci,
            TSK_CFG_INC_TAC: self.cfg_inc_tac,
            TSK_CFG_INC_ENB_ID: self.cfg_inc_enb_id,
            TSK_CFG_INC_MCC: self.cfg_inc_mcc,
            TSK_CFG_INC_MNC: self.cfg_inc_mnc,
            TSK_CFG_INC_EARFCN: self.cfg_inc_earfcn,
            TSK_CFG_INC_CELL_ID: self.cfg_inc_cell_id,
        }
        self.timers = {
            TMR_X2_SETUP: Timer(
                self.x2ap_config["SETUP_PERIOD"],
                callback=self.setup_link,
                retries=(
                    self.x2ap_config["SETUP_RETRIES"]
                    if "SETUP_RETRIES" in self.x2ap_config
                    else 3
                ),
            )
            if "SETUP_PERIOD" in self.x2ap_config
            else None,
            TMR_X2_RESET: Timer(
                self.x2ap_config["RESET_PERIOD"],
                callback=self.disconnect,
                retries=(
                    self.x2ap_config["RESET_RETRIES"]
                    if "RESET_RETRIES" in self.x2ap_config
                    else 3
                ),
            )
            if "RESET_PERIOD" in self.x2ap_config
            else None,
            TMR_ENB_CONFIGURATION_UPDATE: Timer(
                self.x2ap_config["CONFIG_UPDATE_PERIOD"],
                callback=self.send_update,
                retries=(
                    self.x2ap_config["CONFIG_UPDATE_RETRIES"]
                    if "CONFIG_UPDATE_RETRIES" in self.x2ap_config
                    else 3
                ),
            )
            if "CONFIG_UPDATE_PERIOD" in self.x2ap_config
            else None,
        }

    def is_timer_running(self, tname):
        ret = False
        if tname in self.timers and self.timers[tname] is not None:
            ret = self.timers[tname].is_running()
        return ret

    def start_timer(self, tname):
        if tname in self.timers and self.timers[tname] is not None:
            self.timers[tname].start()

    def stop_timer(self, tname):
        if tname in self.timers and self.timers[tname] is not None:
            self.timers[tname].stop()

    def check_timers(self):
        ret = True
        for tname in self.timers.keys():
            if (
                self.timers[tname] is not None
                and self.timers[tname].is_running()
                and self.timers[tname].check_expired()
            ):
                if g_debug: self.log("Timer {} expired.".format(tname))
                ret = False
        return ret

    def get_num_pending_tasks(self):
        return len(self.tasks)

    def put_task(self, task):
        num_pending = self.get_num_pending_tasks()
        if g_debug: self.log("Inserting task={} (pending={}).".format(task, num_pending))
        self.tasks.append(task)

    def process_task(self):
        num_pending = self.get_num_pending_tasks()
        for i in range(num_pending):
            task = self.tasks.popleft()
            if g_debug: self.log("Processing task={} (pending={}).".format(task, num_pending))
            if task in self.task_map:
                self.task_map[task]()
            else:
                self.log("WARNING: process_task: Task not defined: {}".format(task))

    def get_enb_config(self):
        return {"OLD": self.enb_config, "NEW": self.new_enb_config}

    def cfg_inc_pci(self):
        for i, cell in enumerate(self.new_enb_config["SERVED_CELLS"]):
            pci_max = (
                self.new_enb_config["PCI_MAX"]
                if "PCI_MAX" in self.new_enb_config
                else 503
            )
            cell["PCI"] += 3
            if cell["PCI"] >= pci_max + 1:
                cell["PCI"] -= pci_max + 1

    def cfg_inc_cell_id(self):
        for i, cell in enumerate(self.new_enb_config["SERVED_CELLS"]):
            cell["CELL_ID"] += 1
            if cell["CELL_ID"] >= 256:
                cell["CELL_ID"] -= 256

    def cfg_inc_tac(self):
        self.new_enb_config["TAC"] += 1
        if self.new_enb_config["TAC"] > 65535:
            self.new_enb_config["TAC"] = 1

    def cfg_inc_enb_id(self):
        self.new_enb_config["ENB_ID"] += 1000
        if self.new_enb_config["ENB_ID"] > 1048575:
            self.new_enb_config["ENB_ID"] = self.enb_id

    def cfg_inc_mcc(self):
        mcc = int(self.new_enb_config["MCC"])
        mcc += 1
        if mcc > 999:
            mcc = self.mcc
        self.new_enb_config["MCC"] = "{:03d}".format(mcc)

    def cfg_inc_mnc(self):
        mnc = int(self.new_enb_config["MNC"])
        mnc += 10
        if mnc > 999:
            mnc = self.mnc

        if mnc <= 99:
            self.new_enb_config["MNC"] = "{:02d}".format(mnc)
        else:
            self.new_enb_config["MNC"] = "{:03d}".format(mnc)

    def cfg_inc_earfcn(self):
        self.new_enb_config["DL_EARFCN"] += 10
        if self.new_enb_config["DL_EARFCN"] > 65535:
            self.new_enb_config["DL_EARFCN"] = self.dl_earfcn

    def open_client_socket(self):
        try:
            if g_debug: self.log("Creating X2AP Client SCTP socket...")
            self.socket = xsocket.get_sctp_socket(self.local_ip)
            if g_debug: self.log("Binding X2AP Client SCTP socket to local ip addr={}.".format(self.local_ip))
            self.socket.bind((self.local_ip, self.port))
            if g_debug: self.log("Connecting X2AP Client to farend ip addr={}.".format(self.farend_ip))
            xsocket.connect(self.socket, self.farend_ip, self.port)
            if g_enable_prints: self.log("X2AP Client connected {}.".format(self.local_ip))
        except socket.error as err:
            self.logerror("Could not open epx2 client socket: {}.".format(err))
            self.socket.close()
            self.socket = None
        except Exception as ex:
            self.logerror("Exception-open_client_socket[{}]".format(ex))
            self.socket = None

    def close_client_socket(self):
        if self.socket:
            self.socket.shutdown(socket.SHUT_RDWR)
            self.socket.close()
        self.socket = None

    def desc(self):
        return "[{}] (hb:{}, rx:{}, tx:{}, err:{}, state:{}, substate:{}, local={}, far={}, tasks={})".format(
            self.enb_id,
            self.hb,
            self.num_msg_rx,
            self.num_msg_tx,
            self.errors,
            self.link_state,
            self.link_substate,
            self.local_ip,
            self.farend_ip,
            len(self.tasks),
        )

    def send_msg(self, msg_hex, msg_desc):
        if not self.socket:
            self.logerror("Cannot send message {} - no client connected.".format(msg_desc))
            return 0
        try:
            if g_enable_prints: self.log("<--- Sending X2AP {}".format(msg_desc))
            if g_debug: self.logfile("[{}]".format(msg_hex))
            xsocket.send(self.socket, bytes.fromhex(msg_hex))
            self.num_msg_tx += 1
        except Exception as exc:
            self.logerror("Unable to send X2AP {} ({}).".format(msg_desc, exc))
            return 0
        return 1

    def is_link_ready(self):
        if g_debug: self.log("LS = " + self.link_state + ", LSS = " + self.link_substate)
        return self.link_state == LS_CONNECTED and self.link_substate == LSS_NONE

    def setup_link(self):
        if self.is_link_ready():
            self.log("X2AP link is ready")
            return

        if self.is_timer_running(TMR_X2_SETUP):
            self.log("X2AP setup timer is running")
            return

        msg_desc = "X2SetupRequest with PCIs=" if not self.endc else "ENDCX2SetupRequest with PCIs="
        for i, cell in enumerate(self.enb_config["SERVED_CELLS"]):
            msg_desc += "c{}({})".format(i + 1, cell["PCI"])

        msg_str = message_def.X2SetupRequest(self.enb_config) if not self.endc else message_def.ENDCX2SetupRequest(self.enb_config)
        msg_hex = self.asn_coder.encode_asn(msg_str)
        if msg_hex.find("ERROR:") != -1:
            self.logerror("Encoding failure.")
            self.logfile(msg_str)
        elif self.send_msg(msg_hex, msg_desc):
            self.change_state(lss=LSS_SETUP_REQUEST)
            self.start_timer(TMR_X2_SETUP)

    def disconnect(self):
        if not self.is_link_ready():
            if g_debug: print("disconnect: Link not ready, but will do reset")
            #return

        if self.is_timer_running(TMR_X2_RESET):
            if g_debug: print("disconnect: Timer is running")
            return
        else:
            msg_str = message_def.ResetRequest()
            msg_hex = self.asn_coder.encode_asn(msg_str)
            msg_desc = "ResetRequest"
            if msg_hex.find("ERROR:") != -1:
                self.logerror("Encoding failure.")
                self.logfile(msg_str)
            elif self.send_msg(msg_hex, msg_desc):
                self.change_state(lss = LSS_RESET_REQUEST)
                self.start_timer(TMR_X2_RESET)

    def print_enb_config_diff(self, enb_config, new_enb_config):
        msg = "X2_CFG_UPD: "
        if enb_config["MCC"] != new_enb_config["MCC"]:
            msg += "mcc({} -> {}) ".format(enb_config["MCC"], new_enb_config["MCC"])
        if enb_config["MNC"] != new_enb_config["MNC"]:
            msg += "mnc({} -> {}) ".format(enb_config["MNC"], new_enb_config["MNC"])
        if enb_config["ENB_ID"] != new_enb_config["ENB_ID"]:
            msg += "enb_id({} -> {}) ".format(
                enb_config["ENB_ID"], new_enb_config["ENB_ID"]
            )
        if enb_config["TAC"] != new_enb_config["TAC"]:
            msg += "tac({} -> {}) ".format(enb_config["TAC"], new_enb_config["TAC"])
        if enb_config["DL_EARFCN"] != new_enb_config["DL_EARFCN"]:
            msg += "earfcn({} -> {}) ".format(
                enb_config["DL_EARFCN"], new_enb_config["DL_EARFCN"]
            )
        for i, cell in enumerate(enb_config["SERVED_CELLS"]):
            try:
                new_cell = new_enb_config["SERVED_CELLS"][i]
            except IndexError:
                msg += "DEL(s{}) ".format(i)
                continue
            if cell["PCI"] != new_cell["PCI"]:
                msg += "s{}-pci({} -> {}) ".format(i, cell["PCI"], new_cell["PCI"])
            if cell["CELL_ID"] != new_cell["CELL_ID"]:
                msg += "s{}-cell_id({} -> {}) ".format(
                    i, cell["CELL_ID"], new_cell["CELL_ID"]
                )
        self.log(msg)

    def send_update(self):
        if not self.is_link_ready():
            return

        if self.is_timer_running(TMR_ENB_CONFIGURATION_UPDATE):
            return

        if g_enable_prints: self.print_enb_config_diff(self.enb_config, self.new_enb_config)

        msg_str = message_def.ENBConfigurationUpdate(self.enb_config, self.new_enb_config)
        msg_hex = self.asn_coder.encode_asn(msg_str)
        self.enb_config = copy.deepcopy(self.new_enb_config)
        if msg_hex.find("ERROR:") != -1:
            self.logerror("Encoding failure.")
            self.logfile(msg_str)
        elif self.send_msg(msg_hex, "ENBConfigurationUpdate"):
            self.change_state(lss=LSS_CONFIG_UPDATE)
            self.start_timer(TMR_ENB_CONFIGURATION_UPDATE)

    def change_state(self, ls=None, lss=None):
        prev_ls = self.link_state
        prev_lss = self.link_substate

        if ls is not None:
            self.link_state = ls
        if lss is not None:
            self.link_substate = lss

        if (ls is not None) and (ls != prev_ls):
            self.logfile(
                "=== SCE: LS({} -> {}), LSS({} -> {}).".format(
                    prev_ls, self.link_state, prev_lss, self.link_substate
                )
            )
            self.parent_sch.update_status(req=True)

    def process_msg(self, msg_hex_arg):
        recv_msg = "---> Received X2AP "
        self.num_msg_rx += 1
        msg = self.asn_coder.decode_asn(msg_hex_arg)

        if msg.find("ERROR: decoding failed") != -1:
            self.logerror("ASN decoding failed.")
            self.log(msg)
            self.change_state(ls=LS_INIT, lss=LSS_NONE)

        elif msg.find("ENBConfigurationUpdateAcknowledge") != -1:
            if g_enable_prints: self.log(recv_msg + "ENBConfigurationUpdateAcknowledge")
            self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)
            self.stop_timer(TMR_ENB_CONFIGURATION_UPDATE)

        elif msg.find("ENBConfigurationUpdateFailure") != -1:
            self.log(recv_msg + "ENBConfigurationUpdateFailure")
            self.change_state(ls=LS_CONNECTED, lss=LSS_CONFIG_UPDATE_FAILURE)

        elif msg.find("ENBConfigurationUpdate") != -1:
            self.log(recv_msg + "ENBConfigurationUpdate")
            self.change_state(ls=LS_CONNECTED)
            msg_str = message_def.ENBConfigurationUpdateAcknowledge()
            msg_hex = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex, "ENBConfigurationUpdateAcknowledge"):
                self.change_state(lss=LSS_NONE)

        elif msg.find("X2SetupResponse") != -1:
            if g_enable_prints: self.log(recv_msg + "X2SetupResponse")
            self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)
            self.stop_timer(TMR_X2_SETUP)

        elif msg.find("X2SetupFailure") != -1:
            self.log(recv_msg + "X2SetupFailure")
            self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)
            self.stop_timer(TMR_X2_SETUP)
            self.handle_time_to_wait(msg, TMR_X2_SETUP, self.setup_link)

        elif msg.find("ENDCX2SetupFailure") != -1:
            self.log(recv_msg + "ENDCX2SetupFailure")
            self.change_state(ls = LS_CONNECTED, lss = LSS_NONE)
            self.stop_timer(TMR_X2_SETUP)
            self.handle_time_to_wait(msg, TMR_X2_SETUP, self.setup_link)

        elif msg.find("ResetResponse") != -1:
            if g_enable_prints: self.log(recv_msg + "ResetResponse")
            self.change_state(ls = LS_CONNECTED, lss = LSS_NONE)
            self.stop_timer(TMR_X2_RESET)

        elif msg.find("X2SetupRequest") != -1:
            msg_desc = "X2SetupResponse with PCIs="
            for i, cell in enumerate(self.enb_config["SERVED_CELLS"]):
                msg_desc += "c{}({})".format(i + 1, cell["PCI"])

            self.log(recv_msg + "X2SetupRequest")
            msg_str = message_def.X2SetupResponse(self.enb_config)
            msg_hex = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex, msg_desc):
                self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)

        elif msg.find("ENDCX2SetupRequest") != -1:
            msg_desc = "ENDCX2SetupResponse with PCIs="
            for i, cell in enumerate(self.enb_config["SERVED_CELLS"]):
                msg_desc += "c{}({})".format(i + 1, cell["PCI"])

            self.log(recv_msg + "ENDCX2SetupRequest")
            msg_str = message_def.ENDCX2SetupResponse(self.enb_config)
            msg_hex = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex, msg_desc):
                self.change_state(ls = LS_CONNECTED, lss = LSS_NONE)

        elif msg.find("ResetRequest") != -1:
            self.log(recv_msg + "ResetRequest")
            msg_str = message_def.ResetResponse()
            msg_hex = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex, "ResetResponse"):
                self.change_state(ls=LS_CONNECTED, lss=LSS_SETUP_REQUEST)
        elif msg.find("ENDCConfigurationUpdate") != -1:
            self.log(recv_msg + "ENDCConfigurationUpdate")
            msg_desc = "ENDCConfigurationUpdateAcknowledge"
            msg_str = message_def.ENDCConfigurationUpdateAcknowledge(self.enb_config)
            msg_hex = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex, msg_desc):
                self.change_state(lss=LSS_NONE)
        else:
            self.log(recv_msg + "Unknown")
            self.log(msg)

    def handle_time_to_wait(self, msg, timer_name, timer_callback):
        ttw = self.asn_coder.extract_time_to_wait(msg)
        if ttw:
            if timer_name in self.timers:
                self.timers[timer_name].stop()
            new_timer = Timer(ttw, callback=timer_callback)
            self.timers[timer_name] = new_timer
            self.timers[timer_name].start()
            if g_enable_prints: self.log("Started TimeToWait timer {}: {} [s]".format(timer_name, ttw))

    def run(self):
        try:
            self.change_state(ls=LS_INIT, lss=LSS_NONE)

            if self.client is None:
                self.open_client_socket()
            else:
                self.socket = self.client[0]
                self.farend_ip = self.client[1][0]

            self.running = True
            while self.running:
                self.hb += 1
                # self.log(" hb={}, ls={}, lss={}".format(self.hb, self.link_state, self.link_substate))

                if self.errors:
                    self.log("Errors exist. Closing connection...")
                    break

                self.process_task()
                if not self.check_data():
                    break

                self.check_timers()

            self.close_client_socket()
            if g_enable_prints: self.log("X2AP Client disconnected {}...".format(self.local_ip))
            self.change_state(ls=LS_CLOSED, lss=LSS_NONE)
        except Exception as exc:
            self.log(f"Exception: {exc}")
            self.log(traceback.format_exc())
        self.running = False

    def check_data(self):
        if self.socket is None:
            return False

        inputs = [self.socket]
        select_timeout = 1
        ret = True
        try:
            inputready, outputready, exceptready = select.select(
                inputs, [], [], select_timeout
            )
            if len(inputready):
                try:
                    data = xsocket.recv(self.socket)
                    if data:
                        self.logfile(
                            "X2AP Client Data received from {}, len={}.".format(
                                self.local_ip, len(data)
                            )
                        )
                        data = data.hex().upper()
                        if g_debug: self.logfile("[{}]".format(data))
                        self.process_msg(msg_hex_arg=data)
                    else:
                        self.logerror("X2AP Farend connection closed.")
                        ret = False
                except socket.timeout:
                    self.logerror("X2AP Client Socket timeout")
                    ret = False
                except socket.error as err:
                    self.logerror("X2AP Client Socket error:{}".format(err))
                    ret = False
        except select.error as err:
            self.logerror("X2AP Client Data select error: {}.".format(err))
            ret = False
        return ret

    def is_running(self):
        return self.running

    def stop(self):
        self.running = False

    def loginf(self):
        return "[" + str(self.enb_id) + "-" + str(self.farend_ip) + "] "

    def log(self, msg):
        msg_out = self.logfile(msg)
        if self.log_screen:
            print(msg_out)

    def logfile(self, msg):
        msg_out = self.loginf() + str(msg)
        if not self.log_file:
            return msg_out
        if self.logger:
            msg_out = self.logger.write(msg_out)
            self.logger.flush_if_necessary()
        return msg_out

    def logerror(self, msg):
        msg_out = "ERROR: " + msg
        self.log(msg_out)
        self.errors += 1


class SchedulerX2(multiprocessing.Process):
    def __init__(self, id, mdict, enbs, db, mp_pipe, mp_lock, endc):
        super(SchedulerX2, self).__init__()
        self.id = id
        self.mdict = mdict
        self.db = db
        self.mp_pipe = mp_pipe
        self.mp_lock = mp_lock
        self.endc = endc
        self.enbs = []
        self.port = 36422
        self.logger = None
        self.log_screen = db.log_screen
        self.log_file = db.log_file
        self.semaphore = threading.BoundedSemaphore()
        self.running = multiprocessing.Event()

        for enb in enbs:
            self.enbs.append(
                {
                    "ENB_CONFIG": enb,
                    "EPX2S": [],
                    "SERVER": None,
                    "ENB_CONN_VARS": {
                        "num_enb_resets": 0,
                        "num_enb_reinits": 0,
                        "enb_stop_timer": Timer(10),
                    },
                    "SCN_TIMERS": {},
                }
            )

        self.connect_on_start = self.db.get("CONNECT_ON_START", default=False)
        self.server_mode = self.db.get("SERVER_MODE", default=True)
        self.x2_setup_delay = self.db.get("X2_SETUP_DELAY", default=0.1)
        self.start_scn = False
        self.scn_durations = {
#           "X2_SETUP": [
#               self.db.get("X2_SETUP_MIN"),
#               self.db.get("X2_SETUP_MAX"),
#               self.scn_X2_SETUP,
#           ],
            "ENB_CONFIGURATION_UPDATE": [
                self.db.get("ENB_CONFIGURATION_UPDATE_MIN"),
                self.db.get("ENB_CONFIGURATION_UPDATE_MAX"),
                self.scn_ENB_CONFIGURATION_UPDATE,
            ],
            "X2_RESET": [
                self.db.get("X2_RESET_MIN"),
                self.db.get("X2_RESET_MAX"),
                self.scn_X2_RESET,
            ],
#           "LOG_STATUS": [60, 60, self.scn_LOG_STATUS],
        }
        self.cfg_tasks = [
            TSK_CFG_INC_PCI,
            TSK_CFG_INC_TAC,
            # TSK_CFG_INC_ENB_ID,  # Conn reset
            # TSK_CFG_INC_MCC,     # Conn reset
            # TSK_CFG_INC_MNC,     # Conn reset
            TSK_CFG_INC_EARFCN,
            # TSK_CFG_INC_CELL_ID, # Update Failure
        ]
        self.cfg_tasks_idx = 0

    def put_task_all(self, task_name):
        for enb in self.enbs:
            epx2 = self.get_dut_epx2(enb)
            if epx2 is not None:
                epx2.put_task(task_name)

    def put_task_enb(self, task_name, enb):
        epx2 = self.get_dut_epx2(enb)
        if epx2 is not None:
            epx2.put_task(task_name)

    def scn_X2_SETUP(self, enb):
        self.put_task_enb(TSK_X2_SETUP, enb)

    def scn_X2_RESET(self, enb):
        self.put_task_enb(TSK_X2_RESET, enb)

    def scn_ENB_CONFIGURATION_UPDATE(self, enb):
        if self.cfg_tasks_idx >= len(self.cfg_tasks):
            self.cfg_tasks_idx = 0
        self.put_task_enb(self.cfg_tasks[self.cfg_tasks_idx], enb)
        self.cfg_tasks_idx += 1
        self.put_task_enb(TSK_ENB_CONFIGURATION_UPDATE, enb)

    def scn_LOG_STATUS(self, *args):
        self.log_status()

    def log_status(self):
        for enb in self.enbs:
            farend_ip = enb["ENB_CONFIG"]["FAREND_IP"]
            for epx2 in enb["EPX2S"]:
                enb_desc = epx2.desc()
                enb_num_pending_tasks = epx2.get_num_pending_tasks()
                enb_is_running = epx2.is_running()
                if farend_ip == epx2.farend_ip:
                    self.logfile(
                        "{}, pending({}), running=({}), reset({}), reinit({}).".format(
                            enb_desc,
                            enb_num_pending_tasks,
                            enb_is_running,
                            enb["ENB_CONN_VARS"]["num_enb_resets"],
                            enb["ENB_CONN_VARS"]["num_enb_reinits"],
                        )
                    )
                else:
                    self.logfile(
                        "{}, pending({}), running=({}).".format(
                            enb_desc, enb_num_pending_tasks, enb_is_running
                        )
                    )

    # Start already stopped eNB
    def reset_enb(self, enb):
        epx2 = self.get_dut_epx2(enb)
        if epx2 is None:
            return

        # ENB has stopped - is not running
        enb_id = epx2.enb_id
        enb["ENB_CONN_VARS"]["num_enb_resets"] += 1
        if g_debug: self.log("Joining stopped eNB epx2 ({})...".format(enb_id))
        epx2.join()
        if g_debug: self.log("Joined ({}).".format(enb_id))
        self.start_enb(enb)

    # Stop and Start running eNB with errors
    def reinit_enb(self, enb):
        epx2 = self.get_dut_epx2(enb)
        if epx2 is None:
            return

        enb_stop_timer = enb["ENB_CONN_VARS"]["enb_stop_timer"]
        # ENB is hung - is running and blocks sending/receiving
        if enb_stop_timer.is_running():
            if enb_stop_timer.check_expired():
                enb["ENB_CONN_VARS"]["num_enb_reinits"] += 1
                self.log("Reiniting eNB...")
                self.start_enb(enb)
        else:
            epx2.stop()
            enb_stop_timer.start()

    def connect_enbs(self):
        for enb in self.enbs:
            enb_id = enb["ENB_CONFIG"]["ENB_ID"]
            epx2 = self.get_dut_epx2(enb)
            if epx2 is None:
                self.start_enb(enb)
                time.sleep(self.x2_setup_delay)
            elif not epx2.is_running():
                self.reset_enb(enb)

    def disconnect_enb(self, enb_id):
        for enb in self.enbs:
            epx2 = self.get_dut_epx2(enb)
            if epx2 is None:
                continue
            if int(epx2.enb_id) == int(enb_id):
                epx2.stop()

    def scenario(self):
        for enb in self.enbs:
            epx2 = self.get_dut_epx2(enb)
            if epx2 is None:
                continue
            enb_num_pending_tasks = epx2.get_num_pending_tasks()
            if epx2.is_running():
                if enb_num_pending_tasks >= MAX_PENDING_TASKS:
                    self.reinit_enb(enb)
                else:
                    self.check_timers()
            else:
                self.reset_enb(enb)

    def start_scenario(self):
        self.log("Starting traffic control scenario.")
        for enb in self.enbs:
            epx2 = self.get_dut_epx2(enb)
            if epx2 is None:
                self.start_enb(enb)
        self.start_timers()
        self.start_scn = True

    def stop_scenario(self):
        self.log("Stopping traffic control scenario.")
        self.start_scn = False
        self.stop_timers()

    def init_timers(self):
        for enb in self.enbs:
            for scn_key in self.scn_durations.keys():
                dur_min = self.scn_durations[scn_key][0]
                dur_max = self.scn_durations[scn_key][1]
                handler = self.scn_durations[scn_key][2]
                if dur_max:
                    enb["SCN_TIMERS"][scn_key] = Timer(
                        duration=random.randint(dur_min, dur_max),
                        callback=handler,
                        owner=enb,
                    )

    def start_timers(self):
        started = collections.defaultdict(list)
        for enb in self.enbs:
            for scn, timer in enb["SCN_TIMERS"].items():
                timer.start()
                started[scn].append(timer.duration)
        self.log("Started timers: {}".format(started))

    def stop_timers(self):
        for enb in self.enbs:
            for timer in enb["SCN_TIMERS"].values():
                timer.stop()

    def check_timers(self):
        for enb in self.enbs:
            for timer in enb["SCN_TIMERS"].values():
                if timer.check_expired():
                    timer.start()

    def stop(self):
        self.running.clear()

    def is_running(self):
        return self.running.is_set()

    def loginf(self):
        return "[SCHx2-{}] ".format(self.id)

    def logfile(self, msg):
        msg_out = self.loginf() + str(msg)
        if not self.log_file:
            return msg_out
        if self.logger:
            msg_out = self.logger.write(msg_out)
            self.logger.flush_if_necessary()
        else:
            self.logger = Flogger(
                self.db.get_logdir() + "/LOG-EPX2-SCH-" + str(self.id) + ".log"
            )
            self.logger.write("=" * 80)
            self.logger.write("LID=[SCHEDULER]")
            msg_out = self.logger.write(msg_out)
            self.logger.flush_now()
        return msg_out

    def log(self, msg):
        msg_out = self.logfile(msg)
        if self.log_screen:
            print(msg_out)

    def logerror(self, msg):
        msg_out = "ERROR: " + msg
        self.log(msg_out)
        self.mdict["errors"] += 1

    def check_log(self):
        if (
            self.mdict["log_screen"] != self.log_screen
            or self.mdict["log_file"] != self.log_file
        ):
            self.set_log(
                log_screen=self.mdict["log_screen"], log_file=self.mdict["log_file"]
            )

    def set_log(self, log_screen=True, log_file=True):
        if self.log_screen != log_screen:
            self.log_screen = log_screen
            self.set_enb_log()
        self.log_file = log_file
        self.log("Log to screen={}, log to file={}.".format(log_screen, log_file))

    def set_enb_log(self):
        for enb in self.enbs:
            for epx2 in enb["EPX2S"]:
                epx2.log_screen = self.log_screen

    def get_dut_epx2(self, enb):
        farend_ip = enb["ENB_CONFIG"]["FAREND_IP"]
        for epx2 in enb["EPX2S"]:
            if farend_ip == epx2.farend_ip:
                return epx2
        return None

    def dut_epx2_exists(self, enb):
        farend_ip = enb["ENB_CONFIG"]["FAREND_IP"]
        ret = False
        for epx2 in enb["EPX2S"]:
            if farend_ip == epx2.farend_ip and epx2.link_state == LS_CONNECTED:
                ret = True
                break
        return ret

    def start_enb(self, enb):
        server_stopped = False

        if self.dut_epx2_exists(enb):
            if g_enable_prints: self.log("Enb already connected: sch_id={}, enb={}...".format(self.id, enb["ENB_CONFIG"]["ENB_ID"]))
            return

        if g_enable_prints: self.log("Starting scheduler id={} for enb={}...".format(self.id, enb["ENB_CONFIG"]["ENB_ID"]))

        if enb["SERVER"] is not None:
            if g_enable_prints: self.log("X2 Server is running. Stopping before connecting ({})...".format(enb["ENB_CONFIG"]["ENB_ID"]))
            # enb["SERVER"].shutdown(socket.SHUT_RD) #-> [Errno 95] Operation not supported
            enb["SERVER"].close()
            server_stopped = True

        epx2 = ENBConn(
            enb["ENB_CONFIG"],
            enb["ENB_CONFIG"]["IP_ADDR"],
            farend_ip=enb["ENB_CONFIG"]["FAREND_IP"],
            x2ap_config=self.db.get("X2AP"),
            logger=self.logger,
            parent_sch=self,
            log_screen=self.log_screen,
            log_file=self.log_file,
            asn_coder=asncoder.ASNCoder(protocol="X2AP"),
            endc=self.endc,
        )
        epx2.start()
        cnt = 0
        while cnt < 300:
            if epx2.is_running():
                epx2.put_task(TSK_X2_SETUP)
                if g_enable_prints: self.log("ENB started ({}): {}.".format(cnt, epx2.desc()))
                break
            if epx2.link_state == LS_CLOSED:
                if g_enable_prints: self.log("ENB connection closed ({}): {}.".format(cnt, epx2.desc()))
                break
            time.sleep(0.1)
            cnt += 1

        enb["EPX2S"].append(epx2)

        if server_stopped:
            self.open_server_socket(enb)

    def is_pickable(self, obj):
        try:
            pickle.dumps(obj)
        except Exception as exc:
            self.log("WARNING: Not pickable ({}): {}".format(obj, exc))
            return False
        return True

    def update_status(self, req=False):
        if req:
            stime = time.time()
#           if g_debug: self.log("Acquiring STAT mp_lock...")
            self.mp_lock.acquire()
        status = ""
        stat_ls_init = 0
        stat_ls_connected = 0
        stat_ls_closed = 0
        for i, enb in enumerate(self.enbs):
            for epx2 in enb["EPX2S"]:
                status += "  ENB({}):{}\n".format(i, epx2.desc())
                if epx2.link_state == LS_INIT:
                    stat_ls_init += 1
                elif epx2.link_state == LS_CONNECTED:
                    stat_ls_connected += 1
                elif epx2.link_state == LS_CLOSED:
                    stat_ls_closed += 1
        if not req:
            self.semaphore.acquire()

        try:
            if self.is_pickable(status):
                self.mdict["status"] = status
            self.mdict["stat_ls_init"] = stat_ls_init
            self.mdict["stat_ls_connected"] = stat_ls_connected
            self.mdict["stat_ls_closed"] = stat_ls_closed
        except Exception as exc:
            self.log("WARNING: Cannot update status ({}): {}".format(status, exc))

        if not req:
            self.semaphore.release()

        if req:
            self.mp_pipe.send("STAT")
            if self.mp_pipe.poll(5):
                ack = self.mp_pipe.recv_bytes()
            self.mp_lock.release()

    def open_server_sockets(self):
        for enb in self.enbs:
            self.open_server_socket(enb)

    def open_server_socket(self, enb):
        enb["SERVER"] = None
        ip_addr = enb["ENB_CONFIG"]["IP_ADDR"]
        enb_id = enb["ENB_CONFIG"]["ENB_ID"]
        try:
            sctp_sckt = socket.getprotobyname("sctp")
            if g_debug: self.log("Creating EPX2 Server SCTP socket ({})...".format(enb_id))
            server = socket.socket(xsocket.get_socket_type(ip_addr), socket.SOCK_STREAM, sctp_sckt)
            server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            if g_debug: self.log("Binding EPX2 Server SCTP socket to local ip addr={} ({}).".format(ip_addr, enb_id))
            server.bind((ip_addr, self.port))
            if g_enable_prints: self.log("EPX2 Server listening on local ip addr={} ({}).".format(ip_addr, enb_id))
            server.listen(5)
            server.settimeout(0.1)
            enb["SERVER"] = server
        except socket.error as err:
            self.logerror(
                "Could not open epx2 server socket for ip={} ({}): {}.".format(
                    ip_addr, enb_id, err
                )
            )
            if enb["SERVER"]:
                enb["SERVER"].close()
                enb["SERVER"] = None
        except Exception as exc:
            self.logerror(
                "Exception-open_server_socket for ip={} ({}) [{}]".format(
                    ip_addr, enb_id, exc
                )
            )

    def check_server(self):
        inputs = []

        for enb in self.enbs:
            if enb["SERVER"]:
                inputs.append(enb["SERVER"])
            elif self.server_mode:
                self.open_server_socket(enb)

            enb_id = enb["ENB_CONFIG"]["ENB_ID"]
            for epx2 in enb["EPX2S"][:]:
                if epx2.link_state == LS_CLOSED:
                    if g_debug: self.log("Joining closed epx2 for enb={} ({})...".format(enb_id, epx2.desc()))
                    epx2.join()
                    if g_debug: self.log("Joined epx2 for enb={} ({})...".format(enb_id, epx2.desc()))
                    enb["EPX2S"].remove(epx2)

        self.update_status()

        if len(inputs) == 0:
            time.sleep(1)
            return True

        # select_timeout = 10 if self.start_scn else 30
        select_timeout = 1
        ret = True
        try:
            inputready, outputready, exceptready = select.select(
                inputs, [], [], select_timeout
            )
            if len(inputready):
                for inp in inputready:
                    for enb in self.enbs:
                        if inp == enb["SERVER"]:
                            try:
                                conn, addr = inp.accept()
                                self.log(
                                    "EPX2 Server: New connection to {}-{} from {}.".format(
                                        enb["ENB_CONFIG"]["ENB_ID"],
                                        enb["ENB_CONFIG"]["IP_ADDR"],
                                        addr,
                                    )
                                )
                                eclient = ENBConn(
                                    enb["ENB_CONFIG"],
                                    enb["ENB_CONFIG"]["IP_ADDR"],
                                    client=(conn, addr),
                                    logger=self.logger,
                                    parent_sch=self,
                                    log_screen=self.log_screen,
                                    log_file=self.log_file,
                                    asn_coder=asncoder.ASNCoder(protocol="X2AP"),
                                    endc=self.endc,
                                )
                                eclient.start()
                                enb["EPX2S"].append(eclient)

                            except socket.timeout:
                                self.logerror(
                                    "EPX2 Server: Socket timeout, ip={}".format(
                                        enb["ENB_CONFIG"]["IP_ADDR"]
                                    )
                                )
                            except socket.error as err:
                                self.logerror(
                                    "EPX2 Server: Socket error, ip={}: {}".format(
                                        enb["ENB_CONFIG"]["IP_ADDR"], err
                                    )
                                )
                                ret = False
                            except Exception as exc:
                                self.logerror(
                                    "EPX2 Server: Exception for incoming ip={}: {}.".format(
                                        enb["ENB_CONFIG"]["IP_ADDR"], exc
                                    )
                                )
                                ret = False

        except select.error as exc:
            self.logerror("EPX2 Server: Select error: {}.".format(exc))
            ret = False
        except Exception as exc:
            self.logerror("EPX2 Server: Select Exception: {}.".format(exc))
            ret = False
        return ret

    def run(self):
        self.init_timers()
        if self.connect_on_start:
            for enb in self.enbs:
                self.start_enb(enb)
        if self.server_mode:
            self.open_server_sockets()
        self.logfile("Durations={}.".format(self.scn_durations))

        self.running.set()
        try:
            while self.running.is_set():
                self.mdict["hb"] += 1
                self.check_server()
                self.update_status()
                self.check_log()

                if self.mdict["req_stop_scn"]:
                    self.log("Stopping scenario [hb={}]".format(self.mdict["hb"]))
                    self.mdict["req_connect"] = False
                    self.mdict["req_start_scn"] = False
                    self.stop_scenario()
                    self.mdict["req_stop_scn"] = False

                if self.mdict["req_start_scn"]:
                    self.log("Starting scenario [hb={}]".format(self.mdict["hb"]))
                    self.mdict["req_connect"] = False
                    self.start_scenario()
                    self.mdict["req_start_scn"] = False

                if self.start_scn:
                    if g_debug: self.log("Processing scenario [hb={}]".format(self.mdict["hb"]))
                    self.scenario()

                if self.mdict["req_connect"]:
                    # self.log("Connecting eNBs [hb={}]".format(self.mdict["hb"]))
                    self.connect_enbs()
                    # self.mdict["req_connect"] = False

                if self.mdict["req_disconnect"] is not None:
                    self.log("Disconnecting [hb={}]".format(self.mdict["hb"]))
                    self.disconnect_enb(self.mdict["req_disconnect"])
                    self.mdict["req_disconnect"] = None

                if self.mdict["req_task"]:
                    self.log("Requesting task [hb={}]".format(self.mdict["hb"]))
                    task_list = self.mdict["req_task"].split("|")
                    for i, task_name in enumerate(task_list):
                        if i == len(task_list) - 1:
                            break
                        self.log("Putting task={}.".format(task_name))
                        self.put_task_all(task_name)
                    self.mdict["req_task"] = ""
        except Exception as exc:
            self.log(f"Exception: {exc}")
            self.log(traceback.format_exc())

        self.log("Stopping scheduler...")
        for enb in self.enbs:
            if enb["SERVER"]:
                enb["SERVER"].close()
        for enb in self.enbs:
            for epx2 in enb["EPX2S"]:
                epx2.stop()
                if g_debug: self.log("Joining epx2 connection ({}-{})...".format(epx2.enb_id, epx2.farend_ip))
                epx2.join()
                if g_debug: self.log("Joined epx2 conn ({}-{}).".format(epx2.enb_id, epx2.farend_ip))
        self.log("SchedulerX2 stopped.")
        self.running.clear()
